import { test, expect } from '@playwright/test';

test.describe('Multiple Concurrent API Calls', () => {
  const API_BASE_URL = 'https://jsonplaceholder.typicode.com';
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();

    // Set up route interception for API calls
    await page.route(`${API_BASE_URL}/**`, async (route) => {
      await route.continue();
    });
  });

  test('should display data only after all concurrent API calls resolve', async () => {
    // Navigate to a page that makes multiple concurrent API calls
    await page.goto('data:text/html,<html><body><div id="loading">Loading...</div><div id="data"></div></body></html>');

    // Inject script that makes multiple concurrent API calls
    await page.evaluate(async () => {
      const apiBaseUrl = 'https://jsonplaceholder.typicode.com';

      // Show loading state
      document.getElementById('loading').style.display = 'block';
      document.getElementById('data').innerHTML = '';

      try {
        // Make multiple concurrent API calls
        const [users, posts, comments] = await Promise.all([
          fetch(`${apiBaseUrl}/users/1`).then(r => r.json()),
          fetch(`${apiBaseUrl}/posts/1`).then(r => r.json()),
          fetch(`${apiBaseUrl}/comments/1`).then(r => r.json())
        ]);

        // Hide loading and display data
        document.getElementById('loading').style.display = 'none';
        document.getElementById('data').innerHTML = `
          <div class="user-data">User: ${users.name}</div>
          <div class="post-data">Post: ${posts.title}</div>
          <div class="comment-data">Comment: ${comments.body}</div>
        `;
      } catch (error) {
        document.getElementById('loading').style.display = 'none';
        document.getElementById('data').innerHTML = '<div class="error">Error loading data</div>';
      }
    });

    // Wait for loading to disappear
    await page.getByText('Loading...').waitFor({ state: 'hidden', timeout: 10000 });

    // Verify all data is displayed
    await expect(page.getByText(/User:/)).toBeVisible();
    await expect(page.getByText(/Post:/)).toBeVisible();
    await expect(page.getByText(/Comment:/)).toBeVisible();
  });

  test('should handle partial API failures gracefully', async () => {
    await page.goto('data:text/html,<html><body><div id="loading">Loading...</div><div id="data"></div><div id="status"></div></body></html>');

    // Inject script with error handling for concurrent calls
    await page.evaluate(async () => {
      const apiBaseUrl = 'https://jsonplaceholder.typicode.com';

      document.getElementById('loading').style.display = 'block';
      document.getElementById('data').innerHTML = '';
      document.getElementById('status').innerHTML = '';

      try {
        // Make concurrent calls with one intentionally failing
        const results = await Promise.allSettled([
          fetch(`${apiBaseUrl}/users/1`).then(r => r.json()),
          fetch(`${apiBaseUrl}/invalid-endpoint`).then(r => r.json()),
          fetch(`${apiBaseUrl}/posts/1`).then(r => r.json())
        ]);

        document.getElementById('loading').style.display = 'none';

        // Process results
        let successCount = 0;
        let failureCount = 0;
        let dataHtml = '';

        results.forEach((result, index) => {
          if (result.status === 'fulfilled') {
            successCount++;
            if (index === 0) {
              dataHtml += `<div class="success-item">User loaded successfully</div>`;
            } else if (index === 2) {
              dataHtml += `<div class="success-item">Post loaded successfully</div>`;
            }
          } else {
            failureCount++;
            dataHtml += `<div class="failed-item">Request ${index} failed</div>`;
          }
        });

        document.getElementById('data').innerHTML = dataHtml;
        document.getElementById('status').innerHTML = `<div class="status">Success: ${successCount}, Failed: ${failureCount}</div>`;
      } catch (error) {
        document.getElementById('loading').style.display = 'none';
        document.getElementById('data').innerHTML = '<div class="error">Critical error</div>';
      }
    });

    // Wait for loading to disappear
    await page.getByText('Loading...').waitFor({ state: 'hidden', timeout: 10000 });

    // Verify status is displayed
    await expect(page.getByText(/Success:/)).toBeVisible();

    // Verify some items loaded successfully
    await expect(page.getByText(/loaded successfully/)).toBeVisible();
  });

  test('should display data in correct order after concurrent calls complete', async () => {
    await page.goto('data:text/html,<html><body><div id="loading">Loading...</div><div id="results"></div></body></html>');

    await page.evaluate(async () => {
      const apiBaseUrl = 'https://jsonplaceholder.typicode.com';

      document.getElementById('loading').style.display = 'block';

      try {
        // Make concurrent calls and wait for all to resolve
        const [user, post, comment] = await Promise.all([
          fetch(`${apiBaseUrl}/users/1`).then(r => r.json()),
          fetch(`${apiBaseUrl}/posts/1`).then(r => r.json()),
          fetch(`${apiBaseUrl}/comments/1`).then(r => r.json())
        ]);

        document.getElementById('loading').style.display = 'none';

        // Display results in specific order
        const resultsHtml = `
          <div class="result-item" data-order="1">
            <span class="label">User Name:</span>
            <span class="value">${user.name}</span>
          </div>
          <div class="result-item" data-order="2">
            <span class="label">Post Title:</span>
            <span class="value">${post.title}</span>
          </div>
          <div class="result-item" data-order="3">
            <span class="label">Comment Body:</span>
            <span class="value">${comment.body}</span>
          </div>
        `;

        document.getElementById('results').innerHTML = resultsHtml;
      } catch (error) {
        document.getElementById('loading').style.display = 'none';
        document.getElementById('results').innerHTML = '<div class="error">Failed to load data</div>';
      }
    });

    // Wait for loading to disappear
    await page.getByText('Loading...').waitFor({ state: 'hidden', timeout: 10000 });

    // Verify all result items are visible
    const resultItems = page.locator('[data-order]');
    await expect(resultItems).toHaveCount(3);

    // Verify specific content is displayed
    await expect(page.getByText(/User Name:/)).toBeVisible();
    await expect(page.getByText(/Post Title:/)).toBeVisible();
    await expect(page.getByText(/Comment Body:/)).toBeVisible();
  });
});
